import type { MatchSettings } from '../contracts/game';
import type { Hole } from '../courses/types';

/** Extra shots granted over par when a hole does not declare its own budget. */
export const DEFAULT_MAX_SHOTS_OVER_PAR = 7;

/** Penalty strokes booked on top of the budget when a player runs out of shots. */
export const STROKE_LIMIT_PENALTY_STROKES = 1;

/** Hole fields required to resolve a shot budget. */
export type HoleShotBudget = Pick<Hole, 'id' | 'par' | 'maxShots'>;

export type MaxShotsSource = 'hole' | 'settings' | 'par';

export interface MaxShotsResolution {
  maxShots: number;
  source: MaxShotsSource;
}

function isPositiveInteger(value: number | undefined): value is number {
  return value !== undefined && Number.isInteger(value) && value >= 1;
}

/** Resolves the shot budget: hole data wins, then match settings, then par + default. */
export function resolveMaxShotsDetailed(hole: HoleShotBudget, settings?: Pick<MatchSettings, 'strokeLimitPerHole'>): MaxShotsResolution {
  if (hole.maxShots !== undefined) {
    if (!isPositiveInteger(hole.maxShots)) throw new Error(`Hole ${hole.id}: maxShots must be a positive integer`);
    return { maxShots: hole.maxShots, source: 'hole' };
  }
  const configured = settings?.strokeLimitPerHole;
  if (isPositiveInteger(configured)) return { maxShots: configured, source: 'settings' };
  return { maxShots: hole.par + DEFAULT_MAX_SHOTS_OVER_PAR, source: 'par' };
}

export function resolveMaxShots(hole: HoleShotBudget, settings?: Pick<MatchSettings, 'strokeLimitPerHole'>): number {
  return resolveMaxShotsDetailed(hole, settings).maxShots;
}

/** Score booked for a player who never holed out within the budget. */
export function strokeLimitScore(maxShots: number): number {
  return maxShots + STROKE_LIMIT_PENALTY_STROKES;
}
