import { describe, expect, it } from 'vitest';
import type { MatchSettings, PlayerProfile } from '../contracts/game';
import type { Course, Hole } from '../courses/types';
import { validateHole } from '../courses/Hole';
import { MatchManager } from './MatchManager';
import { ScoreManager } from './ScoreManager';
import {
  DEFAULT_MAX_SHOTS_OVER_PAR,
  STROKE_LIMIT_PENALTY_STROKES,
  resolveMaxShots,
  resolveMaxShotsDetailed,
  strokeLimitScore,
} from './StrokeLimit';

const makeHole = (id: string, par: number, maxShots?: number): Hole => ({
  id,
  name: id,
  par,
  ...(maxShots === undefined ? {} : { maxShots }),
  spawn: { x: 0, y: 0, z: 0 },
  cup: { position: { x: 5, y: 0, z: 0 }, radius: 0.3, captureDepth: 0.25 },
  bounds: { min: { x: -2, y: -2, z: -2 }, max: { x: 10, y: 3, z: 2 } },
  surfaces: [],
  obstacles: [],
});

const makePlayer = (id: string): PlayerProfile => ({ id, displayName: id, kind: 'human', ballStyleId: 'default', rating: 1000 });

const settings = (strokeLimitPerHole: number): MatchSettings => ({ courseId: 'c1', maxPlayers: 2, strokeLimitPerHole });

const shot = (playerId: string, holeId: string, sequence: number) => ({
  type: 'shot-accepted' as const,
  command: { playerId, holeId, direction: { x: 1, y: 0, z: 0 }, normalizedPower: 0.5, clientSequence: sequence, issuedAt: 0 },
});

describe('resolveMaxShots', () => {
  it('derives par + DEFAULT_MAX_SHOTS_OVER_PAR when no explicit budget exists', () => {
    expect(resolveMaxShots(makeHole('h1', 3))).toBe(3 + DEFAULT_MAX_SHOTS_OVER_PAR);
    expect(resolveMaxShotsDetailed(makeHole('h1', 3), settings(0)).source).toBe('par');
  });

  it('prefers the budget declared by the hole data', () => {
    expect(resolveMaxShots(makeHole('h1', 3, 5), settings(9))).toBe(5);
    expect(resolveMaxShotsDetailed(makeHole('h1', 3, 5), settings(9)).source).toBe('hole');
  });

  it('falls back to the match setting when the hole omits maxShots', () => {
    expect(resolveMaxShots(makeHole('h1', 3), settings(9))).toBe(9);
    expect(resolveMaxShotsDetailed(makeHole('h1', 3), settings(9)).source).toBe('settings');
  });

  it('rejects invalid hole budgets', () => {
    expect(() => resolveMaxShots({ id: 'h1', par: 3, maxShots: 0 })).toThrow(/maxShots/);
    expect(() => validateHole(makeHole('h1', 4, 3))).toThrow(/maxShots/);
    expect(() => validateHole(makeHole('h1', 4, 4))).not.toThrow();
  });
});

describe('ScoreManager stroke limit', () => {
  it('closes the hole with a penalty result once the budget is spent', () => {
    const manager = new ScoreManager();
    const score = { ...manager.createHoleScore('p1', 'h1'), strokes: 6 };
    expect(manager.applyStrokeLimit(score, 8)).toBe(score);

    const capped = manager.applyStrokeLimit({ ...score, strokes: 8 }, 8);
    expect(capped.completed).toBe(true);
    expect(capped.strokeLimitReached).toBe(true);
    expect(capped.strokes).toBe(strokeLimitScore(8));
    expect(capped.penaltyStrokes).toBe(STROKE_LIMIT_PENALTY_STROKES);
    expect(manager.applyStrokeLimit(capped, 8)).toBe(capped);
    expect(manager.scoreLabel(capped, 3)).toBe('MAX SHOTS');
  });

  it('leaves holed-out scores untouched', () => {
    const manager = new ScoreManager();
    const holed = manager.complete({ ...manager.createHoleScore('p1', 'h1'), strokes: 9 }, 1000);
    expect(manager.applyStrokeLimit(holed, 8)).toBe(holed);
    expect(manager.scoreLabel(holed, 3)).toBe('+6');
  });
});

describe('MatchManager stroke limit enforcement', () => {
  it('auto-completes a hole with a penalty score when the shot budget runs out', () => {
    const course: Course = {
      id: 'c1', name: 'Course', themeId: 'test', version: 1,
      holes: [makeHole('h1', 2, 2), makeHole('h2', 3)],
    };
    const manager = new MatchManager();
    let match = manager.createMatch('m1', settings(0), [makePlayer('p1')]);
    match = manager.startMatch(match, course, 0);
    match = manager.beginAiming(match, course.holes[0]!);

    for (let index = 1; index <= 2; index += 1) {
      match = manager.markShotSubmitted(match);
      match = manager.applySimulationEvent(match, course, shot('p1', 'h1', index), 0);
      match = manager.applySimulationEvent(match, course, { type: 'ball-stopped', playerId: 'p1', position: { x: 1, y: 0, z: 0 } }, 100 * index);
    }

    const holeScore = match.players[0]!.holeScores.find(score => score.holeId === 'h1')!;
    expect(holeScore.completed).toBe(true);
    expect(holeScore.strokeLimitReached).toBe(true);
    expect(holeScore.strokes).toBe(strokeLimitScore(2));
    expect(holeScore.penaltyStrokes).toBe(STROKE_LIMIT_PENALTY_STROKES);
    expect(match.players[0]!.totalStrokes).toBe(strokeLimitScore(2));
    expect(match.currentHoleIndex).toBe(1);
    expect(match.phase).toBe('hole-intro');
  });
});
